mapper.select:
SELECT workspace_id
FROM object_deletion_queue
WHERE next_attempt_at <= #{now}
GROUP BY workspace_id
ORDER BY MIN(next_attempt_at), workspace_id
LIMIT #{limit}

SELECT id, workspace_id AS workspaceId, object_key AS objectKey, attempts
FROM object_deletion_queue
WHERE workspace_id = #{workspaceId} AND next_attempt_at <= #{now}
ORDER BY next_attempt_at, id
LIMIT #{limit}

mapper.update:
UPDATE object_deletion_queue
SET attempts = LEAST(attempts + 1, 2147483647), next_attempt_at = #{nextAttemptAt}
WHERE workspace_id = #{workspaceId} AND id = #{id}

UPDATE object_deletion_queue
SET attempts = LEAST(attempts + 1, 2147483647), next_attempt_at = #{nextAttemptAt}
WHERE workspace_id = #{workspaceId} AND object_key = #{objectKey}
